insert into users (email, passwordHash, handle, name, bio, avatarSeed, createdAt)
     values
            ('maya@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'maya', 'Maya Okafor', 'Chasing ridgelines and early light. Usually somewhere above the treeline.', 'avatar-1', now() - interval '60 days'),
            ('theo@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'theo', 'Theo Lindqvist', 'Architect by day. Bridges, towers and long shadows by night.', 'avatar-2', now() - interval '60 days'),
            ('priya@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'priya', 'Priya Raman', 'Coffee first. Then photos of coffee. Then more coffee.', 'avatar-3', now() - interval '60 days'),
            ('jonas@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'jonas', 'Jonas Weber', 'Salt air, grey water, and lighthouses I haven''t met yet.', 'avatar-4', now() - interval '60 days'),
            ('lena@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'lena', 'Lena Park', 'Shooting on old cameras. Collector of records and small objects.', 'avatar-5', now() - interval '60 days'),
            ('sam@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'sam', 'Sam Rivera', 'Macro and petals. The garden is bigger when you get closer.', 'avatar-6', now() - interval '60 days'),
            ('ada@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'ada', 'Ada Mensah', 'Forty countries and counting. Deserts are my favourite colour.', 'avatar-7', now() - interval '60 days'),
            ('kai@snapgrove.dev', crypt('snapgrove', genSalt('bf', 10)), 'kai', 'Kai Nakamura', 'Rails, roads, and where they go. Mostly the going.', 'avatar-8', now() - interval '60 days');
insert into follows (followerId, followeeId, createdAt)
insert into posts (userId, seedPhoto, caption, createdAt)
     values
            ((select id from users where handle = 'jonas'), 'photo-244', 'This pelican has been on the same post all week.', now() - interval '1309 minutes'),
            ((select id from users where handle = 'sam'), 'photo-306', 'One white flower in the whole bed.', now() - interval '1978 minutes'),
            ((select id from users where handle = 'priya'), 'photo-63', 'Flat white in a red cup. The colour did the work.', now() - interval '2082 minutes'),
            ((select id from users where handle = 'lena'), 'photo-40', 'Portrait of a cat who did not consent to a portrait.', now() - interval '2278 minutes'),
            ((select id from users where handle = 'theo'), 'photo-259', 'Dusk over the expressway, the towers lighting up one by one.', now() - interval '2423 minutes'),
            ((select id from users where handle = 'kai'), 'photo-314', 'Open road. No destination today.', now() - interval '2568 minutes'),
            ((select id from users where handle = 'theo'), 'photo-299', 'Alleys are where the real architecture hides.', now() - interval '2707 minutes'),
            ((select id from users where handle = 'priya'), 'photo-312', 'Morning ritual, same cup for six years.', now() - interval '3091 minutes'),
            ((select id from users where handle = 'lena'), 'photo-39', 'Sunday soundtrack: side B, all the way through.', now() - interval '3217 minutes'),
            ((select id from users where handle = 'lena'), 'photo-45', 'Spotted this van downtown and had to stop.', now() - interval '3893 minutes'),
            ((select id from users where handle = 'ada'), 'photo-288', 'Old town rooftops from the clock tower.', now() - interval '5005 minutes'),
            ((select id from users where handle = 'ada'), 'photo-49', 'Santorini, finally. The white walls are blinding in the best way.', now() - interval '5430 minutes'),
            ((select id from users where handle = 'lena'), 'photo-237', 'Studio assistant on duty. Very serious about it.', now() - interval '5915 minutes'),
            ((select id from users where handle = 'theo'), 'photo-57', 'Empty street, 6am. The city before it wakes up.', now() - interval '6773 minutes'),
            ((select id from users where handle = 'maya'), 'photo-17', 'The trail through the pines this morning. Nobody else for miles.', now() - interval '8023 minutes'),
            ((select id from users where handle = 'kai'), 'photo-88', 'Highway rush from the overpass.', now() - interval '8165 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-10', 'Grey sea, grey sky, perfect day.', now() - interval '9460 minutes'),
            ((select id from users where handle = 'theo'), 'photo-84', 'Suspension cables at night. Engineering is poetry.', now() - interval '9847 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-58', 'Lighthouse number 23 on the list.', now() - interval '9863 minutes'),
            ((select id from users where handle = 'ada'), 'photo-211', 'Tall ships in the old harbour, every house a different colour.', now() - interval '10305 minutes'),
            ((select id from users where handle = 'kai'), 'photo-242', 'Rails at sunset, the best time for trains.', now() - interval '10318 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-74', 'Blue on blue out past the harbour.', now() - interval '11170 minutes'),
            ((select id from users where handle = 'kai'), 'photo-316', 'Boardwalk into the marsh. The quiet kind of route.', now() - interval '11233 minutes'),
            ((select id from users where handle = 'theo'), 'photo-43', 'Brooklyn Bridge in black and white. Some things only work in mono.', now() - interval '11280 minutes'),
            ((select id from users where handle = 'ada'), 'photo-219', 'Safari day three. She walked right past the truck.', now() - interval '11499 minutes'),
            ((select id from users where handle = 'priya'), 'photo-75', 'Grapes from the vineyard tour. Tasted even better than they look.', now() - interval '11873 minutes'),
            ((select id from users where handle = 'sam'), 'photo-55', 'New leaves on the balcony plant. She lives!', now() - interval '12227 minutes'),
            ((select id from users where handle = 'maya'), 'photo-28', 'Found the valley everyone talks about. It''s greener in person.', now() - interval '13726 minutes'),
            ((select id from users where handle = 'ada'), 'photo-247', 'Dunes at golden hour. The sand changes colour every minute.', now() - interval '13843 minutes'),
            ((select id from users where handle = 'priya'), 'photo-292', 'Market haul. Everything is back in season.', now() - interval '14036 minutes'),
            ((select id from users where handle = 'sam'), 'photo-239', 'Make a wish.', now() - interval '14732 minutes'),
            ((select id from users where handle = 'priya'), 'photo-225', 'Afternoon tea, slow steep, no plans.', now() - interval '14874 minutes'),
            ((select id from users where handle = 'kai'), 'photo-233', 'Tracks curving into the hills. The station is a mile that way.', now() - interval '14973 minutes'),
            ((select id from users where handle = 'lena'), 'photo-91', 'New-old camera day. 1978 and still perfect.', now() - interval '15281 minutes'),
            ((select id from users where handle = 'lena'), 'photo-250', 'The rangefinder that started it all.', now() - interval '16047 minutes'),
            ((select id from users where handle = 'maya'), 'photo-18', 'Grass taller than my knees at the trailhead.', now() - interval '16248 minutes'),
            ((select id from users where handle = 'maya'), 'photo-29', 'Snow on the ridge in September. Winter is early up here.', now() - interval '16291 minutes'),
            ((select id from users where handle = 'priya'), 'photo-30', 'Monday mug. Please don''t talk to me for ten minutes.', now() - interval '16300 minutes'),
            ((select id from users where handle = 'sam'), 'photo-35', 'Pollen up close. Bees know what they''re doing.', now() - interval '16800 minutes'),
            ((select id from users where handle = 'kai'), 'photo-69', 'Old branch line, trains stopped running years ago.', now() - interval '17234 minutes'),
            ((select id from users where handle = 'sam'), 'photo-309', 'Backlit leaf, all the little veins showing.', now() - interval '17448 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-77', 'End of the pier. The best seat in town.', now() - interval '17973 minutes'),
            ((select id from users where handle = 'maya'), 'photo-256', 'Fresh powder on the north slope.', now() - interval '18312 minutes'),
            ((select id from users where handle = 'sam'), 'photo-82', 'Cherry blossom season is short, so I went every day.', now() - interval '18518 minutes'),
            ((select id from users where handle = 'maya'), 'photo-287', 'Rolling hills on the way down. Could walk this forever.', now() - interval '18801 minutes'),
            ((select id from users where handle = 'maya'), 'photo-235', 'Summit day. Legs are done, heart is full.', now() - interval '18847 minutes'),
            ((select id from users where handle = 'ada'), 'photo-261', 'Stood in the shadow of this and felt very small.', now() - interval '19027 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-295', 'Storm swell rolling in. Stayed well back for this one.', now() - interval '19212 minutes'),
            ((select id from users where handle = 'theo'), 'photo-238', 'Skyline from the observation deck. Every window a story.', now() - interval '19501 minutes'),
            ((select id from users where handle = 'jonas'), 'photo-14', 'Rocks at low tide. The coast keeps rearranging itself.', now() - interval '19979 minutes');
