-- Eight people who all follow each other, fifty photo posts, likes and
-- comments. Every account signs in with the password "snapgrove", and each
-- has a few unread notifications from the last day.


     select a.id, b.id, now() - interval '30 days' + (random() * interval '10 days')
       from users a
       join users b on a.id <> b.id;




-- Everything older than a day has been seen.
update notifications set readAt = now() where createdAt < now() - interval '1 day';
